/* Danish Names Database — name-meaning lookup demo (jahdb-demo-1.0)
 * RUN ON PC: save as demo.js, then run:  node demo.js [name]
 * RUN IN BROWSER: paste into the console and press Enter. */
var TABLE = {"Jens": "God is gracious — Hebrew Yohanan, via Danish", "Mette": "pearl — Greek margarites, via Margareta", "Lars": "crowned with laurel — Latin Laurentius", "Anne": "grace — Hebrew Hannah", "Peter": "rock, stone — Greek petros", "Hanne": "grace — Hebrew Hannah, via Johannes", "Jensen": "The most common Danish surname.", "Nielsen": "Among the most common Danish surnames.", "Hansen": "A classic -sen surname.", "Pedersen": "A classic -sen surname."};
function lookup(q){
  q=String(q||'').toLowerCase().trim();
  var keys=Object.keys(TABLE);
  for(var i=0;i<keys.length;i++){ if(keys[i].toLowerCase()===q) return keys[i]+' — '+TABLE[keys[i]]; }
  var hits=keys.filter(function(k){return k.toLowerCase().indexOf(q)>=0;});
  if(!hits.length) return 'No match for "'+q+'". Try: '+keys.slice(0,5).join(', ');
  return hits.map(function(k){return k+' — '+TABLE[k];}).join('\n');
}
var q=(typeof process!=='undefined'&&process.argv[2])||'Jens';
console.log(lookup(q));

